/* @autogenerated */
import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { RuntimeConfigService } from '@shared/context/config/app-config.service';
import { LogLevel, Logger, LogRecord, REDACTED, redact, rootLogger } from './logger.service';

describe('redact', () => {
  it('redacts sensitive keys at any depth', () => {
    const result = redact({
      user: 'ana',
      password: 'x',
      nested: { access_token: 'a', refreshToken: 'r', clientSecret: 's', 'x-api-key': 'k' },
      headers: { Authorization: 'Bearer abc' },
      list: [{ apiKey: 'k' }],
    });

    expect(result).toEqual({
      user: 'ana',
      password: REDACTED,
      nested: { access_token: REDACTED, refreshToken: REDACTED, clientSecret: REDACTED, 'x-api-key': REDACTED },
      headers: { Authorization: REDACTED },
      list: [{ apiKey: REDACTED }],
    });
  });

  it('keeps non sensitive keys that only contain the word', () => {
    expect(redact({ tokenEndpointAuthMethod: 'none' })).toEqual({ tokenEndpointAuthMethod: 'none' });
  });

  it('redacts bearer credentials inside strings', () => {
    expect(redact('header Bearer eyJhbGciOi.abc-def')).toBe(`header Bearer ${REDACTED}`);
  });

  it('handles circular references, errors and dates', () => {
    const circular: any = { name: 'a' };
    circular.self = circular;
    const date = new Date('2026-01-01T00:00:00Z');

    expect(redact(circular)).toEqual({ name: 'a', self: '[Circular]' });
    expect(redact(date)).toBe('2026-01-01T00:00:00.000Z');
    expect(redact(new Error('boom'))).toEqual(jasmine.objectContaining({ name: 'Error', message: 'boom' }));
  });
});

describe('Logger', () => {
  let level: ReturnType<typeof signal<LogLevel | undefined>>;
  let logger: Logger;
  let records: LogRecord[];

  beforeEach(() => {
    level = signal<LogLevel | undefined>(undefined);
    TestBed.configureTestingModule({
      providers: [{ provide: RuntimeConfigService, useValue: { value: () => level } }],
    });
    logger = TestBed.inject(Logger);
    records = [];
  });

  afterEach(() => {
    logger.reset();
    TestBed.resetTestingModule();
  });

  it('writes to the console when telemetry is disabled', () => {
    spyOn(console, 'error');

    logger.error('failed', { id: 1 });

    expect(console.error).toHaveBeenCalledWith('failed', { id: 1 });
  });

  it('filters by the minimum level, info by default', () => {
    spyOn(console, 'debug');
    spyOn(console, 'warn');

    logger.debug('hidden');
    expect(console.debug).not.toHaveBeenCalled();

    level.set('error');
    logger.warn('hidden too');
    expect(console.warn).not.toHaveBeenCalled();

    level.set('debug');
    logger.debug('visible');
    expect(console.debug).toHaveBeenCalledWith('visible');
  });

  it('sends redacted records to the remote sink', () => {
    spyOn(console, 'info');
    logger.attachRemote((r) => records.push(r));

    logger.info('login', { user: 'ana', password: 'x' });

    expect(records.length).toBe(1);
    expect(records[0]).toEqual(
      jasmine.objectContaining({ level: 'info', message: 'login', args: [{ user: 'ana', password: REDACTED }] }),
    );
    // La consola local no sale del navegador: recibe el objeto original
    expect(console.info).toHaveBeenCalledWith('login', { user: 'ana', password: 'x' });
  });

  it('rootLogger shares level and sink', () => {
    spyOn(console, 'warn');
    logger.attachRemote((r) => records.push(r));

    rootLogger.warn('from a module function');

    expect(records.map((r) => r.message)).toEqual(['from a module function']);
  });

  it('does not send console.log to the sink unless console is captured', () => {
    spyOn(console, 'log');
    logger.attachRemote((r) => records.push(r));

    console.log('third party log');
    expect(records.length).toBe(0);

    logger.captureConsole();
    console.log('captured', { token: 't' });
    expect(records).toEqual([
      jasmine.objectContaining({ level: 'info', message: 'captured', args: [{ token: REDACTED }] }),
    ]);
  });

  it('with console captured, Logger writes each record to the sink once', () => {
    spyOn(console, 'error');
    logger.attachRemote((r) => records.push(r));
    logger.captureConsole();

    logger.error('once');

    expect(records.length).toBe(1);
  });

  it('reset restores the original console', () => {
    const original = console.log;
    logger.captureConsole();
    expect(console.log).not.toBe(original);

    logger.reset();
    expect(console.log).toBe(original);
  });
});
